import { get, subscribe } from '/app/app/store.js';
import { setActionFeedback } from './action-feedback.js';
import { collectReferralCredits } from './referral-claim.js';

const mounted = new WeakSet();
let busy = false;
let feedback;
const painters = new Set();
export function mountReferralTools(strip) {
  const card = strip.querySelector('.deg-referral-card');
  const custom = document.querySelector('.deg-referral-dialog__custom');
  if (card && custom && !mounted.has(card)) {
    mounted.add(card);
    const banner = document.createElement('div');
    banner.className = 'deg-referral-card site-referral-banner';
    banner.append(...card.childNodes);
    card.classList.add('site-referral-shell');
    card.append(banner, custom);
    custom.classList.add('site-referral-custom');
    const feedback = document.querySelector('[data-bind="deg-referral-dialog-feedback"]');
    if (feedback) {
      card.append(feedback);
      let lastMessage = '';
      new MutationObserver(() => {
        const message = feedback.hidden ? '' : feedback.textContent;
        if (message && message !== lastMessage) setActionFeedback(feedback, message);
        lastMessage = message;
      }).observe(feedback, { childList: true, characterData: true, subtree: true, attributes: true, attributeFilter: ['hidden'] });
    }
    const code = custom.querySelector('[name="deg-referral-code"]');
    const kickback = custom.querySelector('[name="deg-referral-kickback"]');
    const kickbackLabel = kickback.closest('label');
    kickbackLabel.classList.add('site-kickback');
    kickbackLabel.querySelector(':scope > span').textContent = 'KICKBACK %';
    const paint = () => { kickbackLabel.hidden = !code.value.trim(); };
    code.addEventListener('input', paint); paint();
    // Retain the native registration owner, but validate integer percentages
    // before its click handler (the underlying helper parses integers).
    const register = custom.querySelector('[data-bind="deg-referral-register"]');
    register.addEventListener('click', event => {
      if (!code.value.trim() || !code.checkValidity() || !kickback.value || !kickback.checkValidity()) {
        event.stopImmediatePropagation();
        if (!code.value.trim()) code.setCustomValidity('Enter a custom code.');
        else code.setCustomValidity('');
        if (!code.reportValidity()) return;
        if (!kickback.value) kickback.setCustomValidity('Enter a kickback percentage from 0 to 25.');
        kickback.reportValidity();
      }
    }, true);
    code.addEventListener('input', () => code.setCustomValidity(''));
    kickback.addEventListener('input', () => kickback.setCustomValidity(''));
    for (const field of [code, kickback]) field.addEventListener('keydown', event => {
      if (event.key === 'Enter') { event.preventDefault(); register.click(); }
    });
    // The retained banner is also a copy target, using the original copy owner.
    banner.addEventListener('click', event => {
      if (event.target.closest('button,a,input,quest-objective-indicator')) return;
      banner.querySelector('[data-bind="deg-referral-copy"]')?.click();
    });
    banner.title = 'Click for your referral link';
  }
  const panel = strip.querySelector('.site-referrals-inline .aff-content');
  if (!panel || panel.querySelector('.site-collect-credit')) return;
  const button = document.createElement('button');
  button.type = 'button'; button.className = 'site-collect-credit';
  button.textContent = 'COLLECT ALL';
  button.title = 'Collect AFKing affiliate credit from your referral network. Checked only when clicked.';
  const caption = document.createElement('span');
  caption.className = 'site-collect-caption'; caption.textContent = 'AFKing affiliate credit';
  const collect = document.createElement('div'); collect.className = 'site-collect';
  collect.append(caption, button); panel.append(collect);
  if (!feedback) {
    feedback = document.createElement('div'); feedback.setAttribute('role', 'status'); feedback.hidden = true;
    document.body.append(feedback);
  }
  const paint = () => {
    button.disabled = busy || !get('connected.address') || get('ui.chainOk') === false || ['view', 'combined'].includes(get('ui.mode'));
  };
  // Subscribe for this instance only; the native affiliate host is replaced on
  // breakpoint changes, so release these listeners with it.
  const off = ['connected.address', 'ui.chainOk', 'ui.mode'].map(key => subscribe(key, paint));
  painters.add(paint);
  const removal = new MutationObserver(() => {
    if (button.isConnected) return;
    off.forEach(fn => fn()); painters.delete(paint); removal.disconnect();
  });
  removal.observe(strip, { childList: true, subtree: true });
  button.addEventListener('click', async () => {
    if (busy || button.disabled) return;
    const owner = String(get('connected.address')).toLowerCase();
    const checkAccount = () => {
      if (String(get('connected.address') || '').toLowerCase() !== owner) throw Error('Wallet changed. Click Collect All again for this wallet.');
      if (get('ui.chainOk') === false) throw Error('Switch to the game network and try again.');
    };
    busy = true; painters.forEach(fn => fn()); button.textContent = 'CHECKING…'; setActionFeedback(feedback, '');
    try {
      // Even the read dependencies load only after the explicit click.
      const [{ fetchJSON }, { ethers, sendTx, getProvider }, { CONTRACTS }, { permissionlessReadProvider }, { readWalletId }, { abi: affiliateAbi }, { abi: lensAbi }] = await Promise.all([
        import('/app/app/api.js'), import('/app/app/contracts.js'), import('/app/app/chain-config.js'),
        import('/app/app/read-provider.js'), import('/app/app/wallet-id.js'),
        import('/app/chain/generated/affiliate.js'), import('/app/chain/generated/game_lens.js'),
      ]);
      checkAccount();
      const reader = permissionlessReadProvider(getProvider(), { priority: 'interaction' });
      const lens = new ethers.Contract(CONTRACTS.GAME_LENS, lensAbi, reader);
      const result = await collectReferralCredits({
        owner, checkAccount,
        readReferrals: address => fetchJSON(`/player/${address}/referees`),
        readSub: address => lens.subInfoFull(CONTRACTS.GAME, address),
        readId: address => readWalletId(address, { provider: reader }),
        submit: ids => sendTx(signer => {
          checkAccount();
          return new ethers.Contract(CONTRACTS.AFFILIATE, affiliateAbi, signer).claim(ids);
        }, 'Collect AFKing affiliate credit'),
        onProgress: message => { button.textContent = message; },
      });
      setActionFeedback(feedback, result.completed
        ? `Collected AFKing affiliate credit from ${result.completed} referral accounts.`
        : 'No AFKing affiliate credit is ready to collect.');
    } catch (error) {
      setActionFeedback(feedback, `${error.completed ? `Collected from ${error.completed} accounts before stopping. ` : ''}${error.message || 'Collection was not completed.'}`);
    } finally { busy = false; button.textContent = 'COLLECT ALL'; painters.forEach(fn => fn()); }
  });
}
